const email = $input.first().json;

const senderEmail = (email.from?.value?.[0]?.address || email.from || "").toLowerCase();
const senderName  = email.from?.value?.[0]?.name || senderEmail.split("@")[0] || "Lead";
const subject     = email.subject || "(sin asunto)";
const bodyText    = email.text || email.snippet || "(sin contenido)";
const messageId   = email.id || email.messageId || "";
const threadId    = email.threadId || messageId;

// Strip quoted-reply blocks to reduce noise
const cleanBody = bodyText
  .split(/^[-]{2,}\s*Original Message|^On .+ wrote:/mi)[0]
  .replace(/^>.*$/gm, "")
  .trim();

return [{ json: {
  senderEmail,
  senderName,
  subject,
  body: cleanBody,
  rawBody: bodyText,
  messageId,
  threadId,
  receivedAt: email.date || new Date().toISOString()
} }];

const raw = $json.content?.[0]?.text || '{}';
let ext;
try {
  const cleaned = raw.replace(/```json\n?/g,'').replace(/```\n?/g,'').trim();
  ext = JSON.parse(cleaned);
} catch(e) {
  ext = { missing: ['parse_error'], reply_text: 'No hemos podido procesar tu petición automáticamente. Un agente te contactará pronto.' };
}

const prev = $('Preparar payload Claude').item.json;
const missing = Array.isArray(ext.missing) ? ext.missing : [];
const complete = missing.length === 0;

// Fallback: if no contact_email extracted, use the sender's
if (!ext.contact_email && prev.senderEmail) ext.contact_email = prev.senderEmail;
if (!ext.contact_name && prev.senderName) ext.contact_name = prev.senderName;

return [{
  json: {
    ...prev,
    _claudePayload: undefined,
    extraction: ext,
    missing,
    complete
  }
}];

const d = $json;
const ext = d.extraction;

// Compute date_end if only duration_hint
let dateStart = ext.date_start;
let dateEnd = ext.date_end;
if (dateStart && !dateEnd && ext.days_estimate) {
  const start = new Date(dateStart);
  const end = new Date(start.getTime() + ext.days_estimate * 86400000);
  dateEnd = end.toISOString().slice(0, 10);
}
// If no dateStart but has days_estimate: default start = today+3 days
if (!dateStart && ext.days_estimate) {
  const start = new Date(Date.now() + 3 * 86400000);
  const end = new Date(start.getTime() + ext.days_estimate * 86400000);
  dateStart = start.toISOString().slice(0, 10);
  dateEnd = end.toISOString().slice(0, 10);
}

const phoneArr = ext.contact_phone ? [{ value: ext.contact_phone, primary: true, label: "mobile" }] : [];
const emailArr = ext.contact_email ? [{ value: ext.contact_email, primary: true, label: "work" }] : [];

return [{
  json: {
    ...d,
    _normalizedDates: { dateStart, dateEnd },
    _personPayload: {
      name: ext.contact_name || d.senderName,
      email: emailArr,
      phone: phoneArr,
      visible_to: "3"
    }
  }
}];
